#include <bits/stdc++.h>
using namespace std;

typedef bitset<128> Bitset128;

const int MOD = 1000000007;
const int INV = 570000004;

inline int add_mod(int a, int b) {
    int sum = a + b;
    return sum >= MOD ? sum - MOD : sum;
}

inline int sub_mod(int a, int b) {
    int diff = a - b;
    return diff < 0 ? diff + MOD : diff;
}

inline int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

unordered_map<Bitset128, int> index_map;
int node_counter, time_stamp, child_nodes[65536][128];

int dfs(Bitset128 state) {
    auto it = index_map.find(state);
    if (it != index_map.end()) return it->second;
    int id = node_counter++;
    index_map[state] = id;
    for (int mask = 0; mask < (1 << node_counter); ++mask) {
        Bitset128 new_state = state;
        for (int j = 0; j < (1 << node_counter); ++j) {
            if (!new_state[j]) {
                for (int k = mask & j; k; k ^= k & -k) {
                    if (state[j ^ (k & -k)]) {
                        new_state[j] = 1;
                        break;
                    }
                }
            }
        }
        child_nodes[id][mask] = dfs(new_state);
    }
    return id;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
    int n;
    cin >> n;
    dfs(Bitset128(1));
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
        cin >> p[i][j];
        p[i][j] = mul_mod(p[i][j], INV);
    }
    for (int i = 0; i < n; ++i) for (int j = 0; j < (1 << n); ++j) {
        q[i][j] = 1;
        for (int k = 0; k < n; ++k) {
            int val = (j >> k) & 1 ? p[k][i] : sub_mod(1, p[k][i]);
            q[i][j] = mul_mod(q[i][j], val);
        }
    }
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < node_counter; ++j) {
            for (int k = 0; k < (1 << n); ++k) {
                int next_state = child_nodes[j][k];
                dp[i + 1][next_state] = add_mod(dp[i + 1][next_state], mul_mod(dp[i][j], q[i][k]));
            }
        }
    }
    Bitset128 result;
    for (int i = 0; i < (1 << n); ++i) result[i] = 1;
    cout << dp[n][index_map[result]] << endl;
}
